insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('transcription', 'Microsoft Teams (transcription)', 'https://www.microsoft.com/microsoft-teams/', 'Transcrire une réunion ou un entretien tenu en visioconférence, puis relire la transcription pour en faire un compte rendu.', 'Rejoignez ou organisez une réunion Teams. Dans la barre de réunion, ouvrez « Plus » puis « Enregistrer et transcrire » et démarrez la transcription, si l''option est proposée. Prévenez les participants que la transcription est active. À la fin, la transcription est disponible dans l''onglet de la réunion ou dans le chat, selon la configuration. Téléchargez-la et relisez chaque passage avant tout usage.', 'to_validate', 'Compte professionnel ou scolaire Microsoft 365 avec Teams. La fonction peut être désactivée par l''administrateur.', 'depends_on_account', 'Inclus ou non selon la licence Microsoft 365 de l''organisation ; à vérifier auprès de l''administrateur.', 'La disponibilité de la transcription dépend notamment des politiques de l''organisation, des rôles dans la réunion (organisateur, co-organisateur, invité) et des licences. La langue parlée doit être définie correctement. Les transcriptions contiennent des erreurs de reconnaissance et des confusions de locuteurs.', 'Transcription consultable dans Teams ; export en .docx ou .vtt selon la configuration.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Informer explicitement toute personne présente qu''une transcription est en cours ; en formation, n''enregistrer que des échanges joués à partir du cas fictif.', 'https://www.microsoft.com/licensing/terms', 'https://privacy.microsoft.com', 'Utiliser la transcription fictive fournie (R1).', '2026-10-01', 'https://support.microsoft.com/en-us/teams/meetings/i-can-t-transcribe-a-meeting-in-microsoft-teams', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('transcription', 'Outil de transcription validé par la structure', '', 'Carte générique pour l''outil de transcription (dictée, enregistreur, service de transcription) que la structure a autorisé pour ses usages internes.', 'Demandez au formateur ou au référent quel outil est autorisé et avec quel compte. Testez-le sur une phrase courte lue à voix haute. Vérifiez où le fichier audio et la transcription sont stockés. Relisez la transcription en entier avant de la transmettre à un assistant.', 'to_validate', 'Selon l''outil retenu par la structure.', 'unknown', 'À renseigner par la structure selon l''outil choisi.', 'Qualité variable selon le micro, le bruit ambiant et la langue. Les noms propres et les chiffres sont souvent mal transcrits.', 'Selon l''outil : texte brut, .docx, .srt ou .vtt.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier avant usage où sont stockés les enregistrements et pendant combien de temps.', '', '', 'Utiliser la transcription fictive fournie (R1).', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('transcription', 'Transcription fictive fournie (R1)', '', 'Carte de secours : travailler directement à partir de la transcription fictive R1, sans aucun outil de transcription.', 'Ouvrez la ressource R1 dans l''application. Lisez le dialogue en entier. Repérez les faits établis, les points à confirmer et les informations manquantes. Rédigez le compte rendu à partir de ce texte, avec ou sans assistant.', 'authorized', 'Aucun compte nécessaire.', 'free', 'Ressource interne de la formation.', 'Pas de son ni d''enregistrement : l''exercice porte sur la relecture et la rédaction, pas sur la reconnaissance vocale.', 'Texte dans l''application, copiable.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Le texte R1 est fictif ; il ne doit pas être enrichi d''éléments réels.', '', '', 'C''est la carte de secours de la famille Transcription.', null, '', true)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('documents', 'Gemini Notebook (anciennement NotebookLM)', 'https://workspace.google.com/products/gemini-notebook/', 'Importer un ensemble de documents (fiches, procédures, guides) et leur poser des questions avec des réponses qui renvoient aux passages sources.', 'Connectez-vous avec le compte autorisé et créez un carnet. Ajoutez les ressources fictives (R2, R4, R5) en texte ou en fichier. Posez une question précise, par exemple sur les horaires ou les informations manquantes. Ouvrez chaque citation proposée pour vérifier qu''elle dit bien ce que la réponse affirme. Notez la version du document citée.', 'to_validate', 'Compte Google. Les conditions diffèrent selon le type de compte (personnel, Workspace, éducation).', 'depends_on_account', 'Des offres gratuites et payantes existent selon le type de compte et la région ; à revérifier sur le site officiel.', 'Nombre de sources et de carnets limité selon l''offre. Les réponses dépendent entièrement des documents importés : si deux versions contradictoires sont importées, la réponse peut mélanger les deux. Les citations sont à contrôler une par une.', 'Texte collé, PDF, Google Docs, pages web et autres formats selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Les conditions Google diffèrent selon le type de compte (personnel, Workspace, éducation) : vérifier lequel est utilisé avant d''importer un document.', 'https://policies.google.com/terms', 'https://support.google.com/gemininotebook/answer/17004255?hl=en', 'Construire la FAQ à la main à partir des documents, sans outil.', '2026-10-01', 'https://support.google.com/gemininotebook/answer/17004255?hl=en', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('documents', 'Assistant avec pièces jointes', '', 'Carte générique : utiliser un assistant conversationnel autorisé qui accepte des fichiers joints, pour interroger les documents fictifs.', 'Ouvrez l''assistant autorisé par la structure. Joignez ou collez les documents fictifs utiles. Demandez des réponses qui citent le document et le passage exact. Vérifiez chaque citation dans le document d''origine. Signalez dans votre production les réponses que l''assistant n''a pas pu appuyer sur un passage.', 'to_validate', 'Selon l''assistant retenu par la structure.', 'unknown', 'À renseigner selon l''assistant choisi.', 'Taille et nombre de fichiers limités selon l''offre. Les assistants peuvent inventer une citation plausible : seul le document fait foi.', 'Texte collé, PDF, .docx selon l''assistant.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier si les fichiers joints sont conservés par le service et pendant combien de temps.', '', '', 'Construire la FAQ à la main à partir des documents, sans outil.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('documents', 'FAQ texte à partir des documents (sans outil)', '', 'Carte de secours : rédiger une FAQ sourcée en lisant les documents fictifs et en recopiant les passages exacts.', 'Listez cinq questions qu''une personne accompagnée pourrait poser. Cherchez la réponse dans R2, R4 et R5. Pour chaque réponse, notez le code du document, sa version et le passage recopié. Si aucun document ne répond, écrivez « information non disponible » et nommez qui doit la demander.', 'authorized', 'Aucun compte nécessaire.', 'free', 'Aucun coût.', 'Plus lent qu''un outil ; demande une lecture complète des documents.', 'Texte dans le formulaire de production de l''application.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', '', '', 'C''est la carte de secours de la famille Documents.', null, '', true)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('recherche', 'Assistant disposant d''une recherche web', '', 'Carte générique : utiliser un assistant autorisé capable de consulter le web, pour préparer une visite d''entreprise à partir de sources institutionnelles.', 'Partez des points de départ de la ressource R7. Demandez à l''assistant de citer la page précise pour chaque information. Ouvrez chaque page citée et vérifiez le passage exact. Notez la date de publication et la date de consultation. Rejetez toute information que vous ne retrouvez pas sur la page.', 'to_validate', 'Selon l''assistant retenu par la structure.', 'unknown', 'À renseigner selon l''assistant choisi.', 'Les résumés peuvent mélanger plusieurs pages ou dater d''une version ancienne. Certaines pages institutionnelles ne sont pas accessibles à l''outil.', 'Réponses textuelles avec liens.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Ne jamais saisir le nom réel d''un client ou d''une personne dans une requête de recherche pendant la formation.', '', '', 'Utiliser le dossier de pages capturées préparé par le formateur.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('recherche', 'Perplexity', 'https://www.perplexity.ai', 'Moteur de réponse qui propose des réponses accompagnées de liens vers les pages consultées.', 'Ouvrez le site et, si nécessaire, connectez-vous avec le compte autorisé. Saisissez une question précise et, si possible, le nom du site institutionnel visé. Ouvrez chaque lien cité et vérifiez le passage exact. Reportez la page, la date de publication et la date de consultation dans votre fiche de visite.', 'to_validate', 'Utilisation possible sans compte avec des limites ; un compte est demandé pour certaines fonctions.', 'depends_on_account', 'Offre gratuite avec limites et offres payantes ; conditions à revérifier sur le site officiel.', 'Les sources citées ne couvrent pas toujours toute la réponse. Les quotas de requêtes avancées varient selon l''offre.', 'Réponses textuelles avec liens ; export selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', 'https://www.perplexity.ai/hub/legal/terms-of-service', 'https://www.perplexity.ai/hub/legal/privacy-policy', 'Utiliser le dossier de pages capturées préparé par le formateur.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('recherche', 'Dossier de pages capturées préparé par le formateur', '', 'Carte de secours : travailler sur un dossier de pages institutionnelles enregistrées (PDF ou captures) préparé par le formateur, sans accès web.', 'Ouvrez le dossier fourni par le formateur. Pour chaque page, relevez l''adresse, la date de publication si elle figure et la date de capture. Cherchez les informations utiles à la visite et recopiez le passage exact. Remplissez le tableau de sources de la ressource R7.', 'authorized', 'Aucun compte nécessaire.', 'free', 'Aucun coût.', 'Les pages peuvent être anciennes au moment de la formation : indiquer la date de capture.', 'PDF ou images fournis par le formateur.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', '', '', 'C''est la carte de secours de la famille Recherche.', null, '', true)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('schemas', 'Napkin', 'https://www.napkin.ai', 'Transformer un texte (par exemple les six étapes de la procédure R4) en schéma visuel modifiable.', 'Connectez-vous avec le compte autorisé et créez un nouveau document. Collez le texte des six étapes de la procédure fictive. Sélectionnez le passage et demandez une visualisation ; choisissez un style de type parcours ou étapes. Corrigez les libellés pour qu''ils restent fidèles au texte source. Exportez le schéma dans le format autorisé.', 'to_validate', 'Compte requis (adresse e-mail ou compte Google).', 'free_with_quota', 'Offre gratuite avec quotas et marquage ; offres payantes pour lever ces limites. À revérifier sur https://www.napkin.ai/pricing/', 'Quotas de génération et marquage sur l''offre gratuite. Les schémas proposés peuvent réordonner ou fusionner des étapes : vérifier la fidélité au texte.', 'Export PNG, SVG ou PDF selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', 'https://www.napkin.ai/terms', 'https://www.napkin.ai/privacy', 'Utiliser les six blocs éditables de l''application (impression PDF).', '2026-10-01', 'https://www.napkin.ai/pricing/', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('schemas', 'Outil de diagrammes autorisé par la structure', '', 'Carte générique : outil de diagrammes déjà disponible dans la structure (suite bureautique, outil de dessin ou de cartes mentales).', 'Ouvrez l''outil de diagrammes autorisé. Créez six formes reliées par des flèches, une par étape de la procédure R4. Reprenez les libellés exacts des étapes. Ajoutez un titre et la mention du cas fictif. Exportez en PDF ou en image.', 'to_validate', 'Selon l''outil retenu par la structure.', 'unknown', 'À renseigner selon l''outil choisi.', 'Pas de génération automatique : la mise en page est manuelle.', 'Selon l''outil : PDF, PNG, SVG.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', '', '', 'Utiliser les six blocs éditables de l''application (impression PDF).', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('schemas', 'Six blocs éditables dans l''application (impression PDF)', '', 'Carte de secours : remplir six blocs directement dans le formulaire de production de l''application, puis imprimer en PDF.', 'Ouvrez l''atelier Schémas dans l''application. Remplissez les six blocs avec le titre et le contenu de chaque étape. Vérifiez l''ordre et la fidélité au texte R4. Utilisez la fonction d''impression du navigateur pour obtenir un PDF.', 'authorized', 'Aucun compte supplémentaire : accès participant à l''application.', 'free', 'Aucun coût.', 'Mise en forme simple, sans icônes ni flèches personnalisées.', 'PDF via l''impression du navigateur.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', '', '', 'C''est la carte de secours de la famille Schémas.', null, '', true)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('images', 'Outil de génération d''images autorisé', '', 'Carte générique : générer une illustration pour l''affiche « Préparer sa première mission » avec l''outil de génération d''images que la structure a autorisé.', 'Rédigez une description courte de la scène souhaitée, sans texte dans l''image et sans stéréotype. Générez plusieurs variantes. Vérifiez les mains, les objets, la diversité des personnes et l''absence de logo ou de marque réelle. Conservez la variante la plus sobre et notez l''outil utilisé.', 'to_validate', 'Selon l''outil retenu par la structure.', 'unknown', 'À renseigner selon l''outil choisi ; les quotas de génération varient fortement.', 'Le texte intégré aux images est souvent incorrect. Les droits d''usage des images générées dépendent des conditions de l''outil.', 'PNG ou JPEG selon l''outil.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Ne jamais générer l''image d''une personne réelle ; vérifier les conditions d''usage des images produites.', '', '', 'Utiliser des pictogrammes sous licence identifiée et des formes simples.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('images', 'Éditeur de composition (Canva ou équivalent autorisé)', 'https://www.canva.com', 'Composer l''affiche (titre, trois actions, signature) à partir de formes, de pictogrammes et éventuellement d''une image générée.', 'Connectez-vous avec le compte autorisé et créez un format affiche. Placez le titre, les trois actions du brief R6 et la signature « START EVOLUTION ». Utilisez des pictogrammes dont la licence est indiquée. Vérifiez la lisibilité et le contraste. Exportez en PDF ou PNG.', 'to_validate', 'Compte requis ; les fonctions disponibles dépendent de l''offre.', 'depends_on_account', 'Offre gratuite avec limites et offres payantes ; certains éléments de la bibliothèque sont payants. À revérifier sur le site officiel.', 'Certains éléments graphiques sont réservés aux offres payantes. Les fonctions d''IA intégrées ont leurs propres quotas et conditions.', 'PDF, PNG, JPEG.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier la licence de chaque élément graphique utilisé.', 'https://www.canva.com/policies/terms-of-use/', 'https://www.canva.com/policies/privacy-policy/', 'Utiliser des pictogrammes sous licence identifiée et des formes simples.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('images', 'Pictogrammes sous licence identifiée et formes simples', '', 'Carte de secours : composer l''affiche avec des pictogrammes dont la licence est connue et des formes simples, dans un outil bureautique ou dans l''application.', 'Choisissez trois pictogrammes (horaires, questions, trajet) dont la licence est indiquée et notez leur source. Placez le titre, les trois actions et la signature textuelle « START EVOLUTION ». Utilisez des formes simples (cadres, flèches) pour structurer l''affiche. Exportez ou imprimez en PDF.', 'authorized', 'Aucun compte nécessaire.', 'free', 'Aucun coût si les pictogrammes sont sous licence libre ou fournis par la structure.', 'Rendu plus sobre qu''une image générée ; le choix des pictogrammes demande de vérifier la licence.', 'PDF, PNG.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Indiquer la source et la licence de chaque pictogramme.', '', '', 'C''est la carte de secours de la famille Images.', null, '', true)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('assistants', 'ChatGPT', 'https://chatgpt.com', 'Assistant conversationnel généraliste, utilisable pour rédiger, reformuler ou comparer des réponses à partir du cas fictif.', 'Connectez-vous avec le compte autorisé. Utilisez le constructeur de prompt de l''application pour préparer votre demande (contexte, tâche, données fictives, contraintes, format, contrôles). Collez-la dans l''assistant. Comparez la réponse avec les documents sources et notez les écarts.', 'to_validate', 'Compte requis pour la plupart des usages ; les offres et fonctions varient selon le compte.', 'depends_on_account', 'Offre gratuite avec limites et offres payantes ; conditions à revérifier sur le site officiel.', 'Quotas de messages et accès aux fonctions avancées selon l''offre. L''assistant peut produire des informations plausibles mais fausses.', 'Texte, fichiers joints et images selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier les réglages de conservation et d''utilisation des conversations.', 'https://openai.com/policies/terms-of-use/', 'https://openai.com/policies/privacy-policy/', 'Utiliser la comparaison de deux réponses d''exemple fournie par le formateur.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('assistants', 'Claude', 'https://claude.ai', 'Assistant conversationnel généraliste, utilisable pour rédiger, structurer ou comparer des réponses à partir du cas fictif.', 'Connectez-vous avec le compte autorisé. Préparez votre demande avec le constructeur de prompt de l''application. Collez-la dans l''assistant et demandez une réponse qui distingue faits établis, points à confirmer et informations manquantes. Relisez la réponse face aux documents sources.', 'to_validate', 'Compte requis ; les offres et fonctions varient selon le compte.', 'depends_on_account', 'Offre gratuite avec limites et offres payantes ; conditions à revérifier sur le site officiel.', 'Quotas d''usage selon l''offre. L''assistant peut inventer des détails s''ils manquent dans les documents fournis.', 'Texte, fichiers joints et images selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier les réglages de conservation et d''utilisation des conversations.', 'https://www.anthropic.com/legal/consumer-terms', 'https://www.anthropic.com/legal/privacy', 'Utiliser la comparaison de deux réponses d''exemple fournie par le formateur.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('assistants', 'Gemini', 'https://gemini.google.com', 'Assistant conversationnel généraliste de Google, utilisable pour rédiger ou comparer des réponses à partir du cas fictif.', 'Connectez-vous avec le compte Google autorisé. Préparez votre demande avec le constructeur de prompt de l''application. Collez-la dans l''assistant et demandez des réponses qui signalent les informations manquantes. Relisez la réponse face aux documents sources.', 'to_validate', 'Compte Google requis ; les conditions diffèrent selon le type de compte (personnel, Workspace, éducation).', 'depends_on_account', 'Offre gratuite avec limites et offres payantes ; conditions à revérifier sur le site officiel.', 'Quotas et fonctions selon le type de compte. L''assistant peut produire des informations plausibles mais fausses.', 'Texte, fichiers joints et images selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier les réglages d''activité et de conservation du compte Google.', 'https://policies.google.com/terms', 'https://policies.google.com/privacy', 'Utiliser la comparaison de deux réponses d''exemple fournie par le formateur.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('assistants', 'Le Chat (Mistral)', 'https://chat.mistral.ai', 'Assistant conversationnel généraliste de Mistral AI, utilisable pour rédiger ou comparer des réponses à partir du cas fictif.', 'Connectez-vous avec le compte autorisé. Préparez votre demande avec le constructeur de prompt de l''application. Collez-la dans l''assistant et demandez une réponse structurée. Relisez la réponse face aux documents sources et notez les écarts.', 'to_validate', 'Compte requis ; les offres et fonctions varient selon le compte.', 'depends_on_account', 'Offre gratuite avec limites et offres payantes ; conditions à revérifier sur le site officiel.', 'Quotas d''usage selon l''offre. L''assistant peut produire des informations plausibles mais fausses.', 'Texte et fichiers joints selon l''offre.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Vérifier les réglages de conservation et d''utilisation des conversations.', 'https://mistral.ai/terms', 'https://mistral.ai/terms#privacy-policy', 'Utiliser la comparaison de deux réponses d''exemple fournie par le formateur.', null, '', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('assistants', 'Microsoft Copilot', 'https://copilot.microsoft.com', 'Assistant conversationnel de Microsoft, utilisable avec un compte personnel ou professionnel pour rédiger ou comparer des réponses à partir du cas fictif.', 'Connectez-vous avec le compte autorisé par la structure. Vérifiez quel mode est actif (compte personnel ou compte professionnel) car les protections diffèrent. Préparez votre demande avec le constructeur de prompt de l''application et collez-la. Relisez la réponse face aux documents sources.', 'to_validate', 'Compte Microsoft personnel, professionnel ou scolaire ; les fonctionnalités dépendent du compte et des licences.', 'depends_on_account', 'Accès de base avec un compte ; fonctions supplémentaires soumises à une licence Microsoft 365 Copilot. À revérifier auprès de l''administrateur.', 'Les fonctionnalités dépendent du compte et des licences : l''accès aux documents de l''organisation, les protections de données et certaines fonctions ne sont disponibles qu''avec une licence Microsoft 365 Copilot.', 'Texte, fichiers joints et images selon le compte.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données. Ne pas confondre le mode personnel et le mode professionnel : vérifier l''indication affichée dans l''interface.', 'https://www.microsoft.com/licensing/terms', 'https://privacy.microsoft.com', 'Utiliser la comparaison de deux réponses d''exemple fournie par le formateur.', '2026-10-01', 'https://support.microsoft.com/en-us/microsoft-365-copilot/how-copilot-chat-works-with-and-without-a-microsoft-365-copilot-license', false)
  on conflict (family, name) do nothing;
insert into public.tool_cards (family, name, official_url, usage, quick_start, authorization_status, account_required, pricing_status, pricing_note, limits, formats, precautions, terms_url, privacy_url, fallback, last_verified_on, verification_source, is_fallback) values ('assistants', 'Comparaison de deux réponses d''exemple', '', 'Carte de secours : comparer deux réponses d''assistants fournies par le formateur, sans accès à un assistant.', 'Ouvrez les deux réponses d''exemple fournies par le formateur pour le même prompt. Repérez pour chacune les faits exacts, les erreurs et les informations inventées par rapport aux documents sources. Remplissez la grille de comparaison de l''application. Concluez sur l''assistant le plus adapté à cette tâche et à ces contraintes, sans classement général.', 'authorized', 'Aucun compte nécessaire.', 'free', 'Aucun coût.', 'Les réponses sont figées ; l''exercice porte sur l''analyse, pas sur la manipulation d''un outil.', 'Texte fourni par le formateur.', 'Données fictives uniquement (cas Agence Horizon) : ne pas coller de données réelles, ni de noms, ni de coordonnées de personnes accompagnées ou de clients. Pas de partage de comptes entre participants. Respecter les quotas et les conditions d''utilisation. Aucun des éléments de cette carte (conditions, politique de confidentialité, lieu d''hébergement annoncé) ne prouve à lui seul une conformité RGPD : la validation revient à la structure et à son délégué à la protection des données.', '', '', 'C''est la carte de secours de la famille Assistants.', null, '', true)
  on conflict (family, name) do nothing;

-- Questions de contrôle (débrief)
insert into public.quiz_questions (position, question, options, correct_index, explanation) values (1, 'Vous rédigez un compte rendu à partir d''une fiche mission et d''un entretien. Aucun des deux documents ne donne le salaire. Que faites-vous ?', $j$["Je reprends le salaire habituel pour ce type de poste, que je connais par expérience.","Je demande à un assistant une estimation et je l'indique avec la mention « environ ».","J'écris « information non disponible » et j'attribue à une personne responsable le soin de la demander au client.","Je laisse la ligne vide : la personne accompagnée posera la question elle-même."]$j$::jsonb, 2, 'Une information absente des sources doit être reconnue comme manquante, pas comblée par une habitude, une estimation ou un assistant. L''écrire explicitement (« information non disponible ») évite qu''un lecteur pressé la prenne pour oubliée ou sans importance. L''attribuer à une personne responsable, avec une échéance, transforme le manque en action de suivi. Une ligne vide, elle, ne dit à personne qui doit agir.')
  on conflict (position) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (position, question, options, correct_index, explanation) values (2, 'Avant de transmettre un entretien à un assistant, vous remplacez le nom de la personne par « P1 ». Que pouvez-vous affirmer ?', $j$["Le texte est anonymisé : il peut être transmis à n'importe quel outil.","Le texte est au mieux pseudonymisé : les autres éléments (lieu, dates, parcours, situation) peuvent encore permettre de réidentifier la personne.","Le texte est conforme au RGPD puisqu'il ne contient plus de nom.","Le texte peut être conservé sans limite de durée puisqu'il n'est plus personnel."]$j$::jsonb, 1, 'Remplacer un nom par un identifiant ne supprime pas le lien avec la personne : c''est une pseudonymisation, et les données restent des données personnelles. Un lieu, une date de début, une situation de transport ou un parcours professionnel suffisent souvent à réidentifier quelqu''un, surtout dans une petite agence. L''anonymisation suppose qu''aucune réidentification raisonnable ne soit possible, ce qu''un simple remplacement de nom ne garantit pas. C''est pourquoi la formation travaille uniquement sur des cas fictifs.')
  on conflict (position) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (position, question, options, correct_index, explanation) values (3, 'Vous voulez mesurer le temps gagné grâce à un assistant pour rédiger un compte rendu. Quel calcul est le plus honnête ?', $j$["Le temps de génération de la réponse par l'assistant, puisque c'est lui qui fait le travail.","Le temps habituel moins le temps de génération, sans compter la relecture qui serait faite de toute façon.","Le temps total incluant la préparation du prompt et des données, la génération, la vérification et la correction, comparé au temps habituel.","Le temps déclaré par l'éditeur de l'outil dans sa documentation."]$j$::jsonb, 2, 'Un gain de temps ne se mesure pas sur la seule génération : préparer le contexte, sélectionner les données fictives, vérifier chaque fait contre les sources et corriger les erreurs font partie de la tâche. Oublier ces étapes gonfle artificiellement le gain et masque le risque d''une erreur non repérée. La comparaison honnête met face à face le temps habituel complet et le temps observé complet, sur une tâche réellement testée. C''est ce que demande le plan d''action de la formation avec la case « temps observé testé ».')
  on conflict (position) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (position, question, options, correct_index, explanation) values (4, 'Deux documents sur la même mission donnent des horaires différents : 8 h à 16 h dans l''un, 9 h à 17 h dans l''autre. Que faites-vous en premier ?', $j$["Je retiens les horaires les plus courants dans ce secteur.","Je fais la moyenne des deux et j'écris « environ 8 h 30 à 16 h 30 ».","J'examine les dates, les versions et le champ d'application de chaque document pour savoir lequel fait foi, puis je signale ce qui reste à confirmer.","Je demande à un assistant de trancher et je reprends sa réponse."]$j$::jsonb, 2, 'Une contradiction entre sources se résout d''abord par l''examen des documents eux-mêmes : lequel est le plus récent, lequel est marqué comme obsolète, à quel périmètre chacun s''applique (horaires provisoires, présence indicative, semaine suivante). Dans le cas fictif, la V1 du 10/09 est explicitement remplacée par la V2 du 18/09, qui reste elle-même « à confirmer par le client ». Une moyenne, une habitude de secteur ou l''avis d''un assistant n''ont aucune valeur de preuve. Ce qui n''est pas tranché par les documents doit être noté comme point à confirmer.')
  on conflict (position) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (position, question, options, correct_index, explanation) values (5, 'À l''issue de la comparaison de deux assistants, un participant demande : « Lequel est le meilleur ? » Quelle réponse est la plus juste ?', $j$["Celui qui a obtenu la note la plus élevée dans les classements publics.","Celui qui a donné la réponse la plus longue et la plus détaillée.","Cela dépend de la tâche et des contraintes données : données autorisées, compte disponible, besoin de citations, temps de vérification ; il n'y a pas de classement universel.","Celui dont l'abonnement est le plus cher, puisque les fonctions sont plus nombreuses."]$j$::jsonb, 2, 'Le choix d''un assistant se décide pour une tâche précise et dans un cadre précis : quelles données on a le droit de lui confier, quel compte la structure autorise, s''il faut des citations vérifiables, combien de temps on peut consacrer à la relecture. Un outil excellent pour un résumé peut être inadapté pour une recherche sourcée, et inversement. Les classements publics et le prix des abonnements évoluent vite et ne disent rien du contexte de l''agence. La grille de comparaison de la formation sert justement à fonder la décision sur des critères observés, pas sur une réputation.')
  on conflict (position) do update set question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;

commit;
